"use strict";(globalThis.webpackChunk=globalThis.webpackChunk||[]).push([[4878],{8447(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/axiomara-website/docs/intro","label":"Getting Started","docId":"intro","unlisted":false},{"type":"link","href":"/axiomara-website/docs/architecture/overview","label":"Architecture","docId":"architecture/overview","unlisted":false},{"type":"link","href":"/axiomara-website/docs/engine/overview","label":"Trading Engine","docId":"engine/overview","unlisted":false},{"type":"link","href":"/axiomara-website/docs/strategy/overview","label":"Strategy Framework","docId":"strategy/overview","unlisted":false},{"type":"link","href":"/axiomara-website/docs/trading/overview","label":"Trading Module","docId":"trading/overview","unlisted":false}]},"docs":{"architecture/overview":{"id":"architecture/overview","title":"Architecture Overview","description":"Axiomara is a containerised platform for designing, backtesting, and analysing quantitative trading strategies. It combines a Python-based trading engine, a FastAPI backend, a Next.js frontend, and an LLM-powered agent service into a single Docker Compose stack. This document provides a high-level view of the system architecture: the major services, how they communicate, the storage layers that persist data and artefacts, the Docker Compose topology that ties everything together, and the testing infrastructure that keeps the codebase reliable. It is aimed at technical readers who need to navigate, extend, or operate the platform.","sidebar":"tutorialSidebar"},"engine/overview":{"id":"engine/overview","title":"Trading Engine Overview","description":"The trading engine is the main service in the Axiomara Docker Compose stack. It is a Python application that receives commands over Redis pub/sub, executes them, and persists results to PostgreSQL and MinIO. It does not expose any HTTP API \u2014 it is driven entirely by messages published by the backend. The engine is built around three core modules: components, strategy, and trading. The strategy module defines the interface and lifecycle for trading strategies and is documented in the Strategy Overview. The trading module provides portfolio management, order execution, risk enforcement, and rebalancing and is documented in the Trading Overview. This document focuses on the components module, which contains the top-level use cases that orchestrate the engine\'s work.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Getting Started","description":"This guide walks you through the Axiomara platform from first launch to inspecting backtest results. By the end, you will know how to manage strategies, download market data, run experiments, and analyse trial outcomes \u2014 using either the Python client library or the REST API directly.","sidebar":"tutorialSidebar"},"strategy/overview":{"id":"strategy/overview","title":"Strategy Framework Overview","description":"The Axiomara strategy framework provides a structured, signal-based approach to building quantitative trading strategies. Rather than managing orders directly, strategy authors implement a single generate_signals() method, and the framework takes care of order conversion, risk validation, and submission. Strategies run in repeating cycles -- each cycle ingests fresh market data, enforces risk guardrails, executes user-defined logic, and submits validated orders -- giving developers a clear, hook-driven lifecycle they can extend at every stage. This document is a comprehensive reference: it covers the execution flow, the signal architecture, the strategy creation process, the full API surface, and the mechanisms for loading and discovering strategies.","sidebar":"tutorialSidebar"},"trading/overview":{"id":"trading/overview","title":"Trading Module Overview","description":"The trading module is one of the three core modules that make up the Axiomara trading engine, alongside the strategy module and the components module. While the strategy module defines what to trade and the components module provides shared infrastructure, the trading module handles how trading is executed: it manages orders and transfers, tracks portfolio state, enforces risk guardrails, and rebalances assets across exchanges. Users do not interact with this module directly \u2014 it is consumed by the trading engine and by strategies through well-defined interfaces.","sidebar":"tutorialSidebar"}}}}')}}]);